    while True:
        print('\n1. إضافة مهمة\n2. عرض المهام\n3. إنجاز مهمة\n4. خروج')
        choice = input('اختر: ')
        if choice == '1':
            title = input('عنوان المهمة: ')
            manager.add_task(title)
        elif choice == '2':
            manager.list_tasks()
        elif choice == '3':
            manager.list_tasks()
            idx = int(input('رقم المهمة: ')) - 1
            manager.mark_done(idx)
        elif choice == '4':
            break
        else:
            print('اختيار خاطئ.')

