import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

class Account {
    private String owner;
    private double balance;

    public Account(String owner, double initialBalance) {
        this.owner = owner;
        this.balance = initialBalance;
    }

    public void deposit(double amount) {
        if (amount > 0) balance += amount;
    }

    public void withdraw(double amount) {
        if (amount > 0 && amount <= balance) balance -= amount;
        else System.out.println("رصيد غير كافٍ");
    }

    public double getBalance() { return balance; }
    public String getOwner() { return owner; }
}

public class BankSystem {
    public static void main(String[] args) {
        List<Account> accounts = new ArrayList<>();
        Scanner scanner = new Scanner(System.in);
        while (true) {
            System.out.println("1. إنشاء حساب\n2. إيداع\n3. سحب\n4. عرض\n5. خروج");
            int choice = scanner.nextInt();
            scanner.nextLine();
            switch (choice) {
                case 1:
                    System.out.print("اسم المالك: ");
                    String name = scanner.nextLine();
                    System.out.print("الرصيد الابتدائي: ");
                    double bal = scanner.nextDouble();
                    accounts.add(new Account(name, bal));
                    break;
                case 2:
                    System.out.print("رقم الحساب: ");
                    int idx = scanner.nextInt() - 1;
                    if (idx >= 0 && idx < accounts.size()) {
                        System.out.print("المبلغ: ");
                        accounts.get(idx).deposit(scanner.nextDouble());
                    }
                    break;
                case 3:
                    System.out.print("رقم الحساب: ");
                    idx = scanner.nextInt() - 1;
                    if (idx >= 0 && idx < accounts.size()) {
                        System.out.print("المبلغ: ");
                        accounts.get(idx).withdraw(scanner.nextDouble());
                    }
                    break;
                case 4:
                    for (int i = 0; i < accounts.size(); i++) {
                        System.out.println((i+1) + ". " + accounts.get(i).getOwner() + " - " + accounts.get(i).getBalance());
                    }
                    break;
                case 5:
                    return;
            }
        }
    }
}

