use std::fs;
use std::io::{self, Write};
use std::path::Path;

#[derive(Debug)]
struct Task {
    title: String,
    done: bool,
}

fn load_tasks(filename: &str) -> Vec<Task> {
    let mut tasks = Vec::new();
    if let Ok(content) = fs::read_to_string(filename) {
        for line in content.lines() {
            let parts: Vec<&str> = line.split('|').collect();
            if parts.len() == 2 {
                tasks.push(Task {
                    title: parts[0].to_string(),
                    done: parts[1] == "1",
                });
            }
        }
    }
    tasks
}

fn save_tasks(filename: &str, tasks: &[Task]) {
    let mut output = String::new();
    for task in tasks {
        output.push_str(&format!("{}|{}\n", task.title, if task.done { 1 } else { 0 }));
    }
    fs::write(filename, output).expect("تعذر الحفظ");
}

fn main() {
    let filename = "tasks.txt";
    let mut tasks = load_tasks(filename);
    loop {
        println!("\n1. إضافة مهمة\n2. عرض المهام\n3. إنجاز مهمة\n4. خروج");
        print!("اختر: ");
        io::stdout().flush().unwrap();
        let mut choice = String::new();
        io::stdin().read_line(&mut choice).unwrap();
        match choice.trim() {
            "1" => {
                print!("عنوان المهمة: ");
                io::stdout().flush().unwrap();
                let mut title = String::new();
                io::stdin().read_line(&mut title).unwrap();
                tasks.push(Task { title: title.trim().to_string(), done: false });
                save_tasks(filename, &tasks);
            }
            "2" => {
                for (i, task) in tasks.iter().enumerate() {
                    let status = if task.done { "✓" } else { "✗" };
                    println!("{}. [{}] {}", i + 1, status, task.title);
                }
            }
            "3" => {
                print!("رقم المهمة: ");
                io::stdout().flush().unwrap();
                let mut idx = String::new();
                io::stdin().read_line(&mut idx).unwrap();
                if let Ok(n) = idx.trim().parse::<usize>() {
                    if n > 0 && n <= tasks.len() {
                        tasks[n - 1].done = true;
                        save_tasks(filename, &tasks);
                    }
                }
            }
            "4" => break,
            _ => println!("اختيار خاطئ"),
        }
    }
}

