        this.bindEvents();
    }

    save() {
        localStorage.setItem('tasks', JSON.stringify(this.tasks));
    }

    addTask(title, priority = 'medium') {
        this.tasks.push({
            id: Date.now(),
            title,
            completed: false,
            priority,
            createdAt: new Date().toISOString()
        });
        this.save();
        this.render();
    }

    deleteTask(id) {
        this.tasks = this.tasks.filter(t => t.id !== id);
        this.save();
        this.render();
    }

    toggleTask(id) {
        const task = this.tasks.find(t => t.id === id);
        if (task) {
            task.completed = !task.completed;
            this.save();
            this.render();
        }
    }

    editTask(id, newTitle) {
        const task = this.tasks.find(t => t.id === id);
        if (task) {
            task.title = newTitle;
            this.save();
            this.render();
        }
    }

    getFilteredTasks() {
        switch (this.filter) {
            case 'active': return this.tasks.filter(t => !t.completed);
            case 'completed': return this.tasks.filter(t => t.completed);
            default: return this.tasks;
        }
    }

    getStats() {
        const total = this.tasks.length;
        const completed = this.tasks.filter(t => t.completed).length;
        const active = total - completed;
        const highPriority = this.tasks.filter(t => t.priority === 'high' && !t.completed).length;
        return { total, completed, active, highPriority };
    }

    render() {
        const list = document.getElementById('taskList');
        const filtered = this.getFilteredTasks();
        const stats = this.getStats();

        document.getElementById('stats').innerHTML = `
            <span>الكل: ${stats.total}</span>
            <span>النشطة: ${stats.active}</span>
            <span>المكتملة: ${stats.completed}</span>
            <span>أولوية عالية: ${stats.highPriority}</span>
        `;

        if (filtered.length === 0) {
            list.innerHTML = '<li class="empty">لا توجد مهام</li>';
            return;
        }

        list.innerHTML = filtered.map(task => `
            <li class="task ${task.completed ? 'completed' : ''} priority-${task.priority}"
                draggable="true" data-id="${task.id}">
                <input type="checkbox" ${task.completed ? 'checked' : ''}
                       onchange="app.toggleTask(${task.id})">
                <span class="title" ondblclick="app.startEdit(${task.id})">
                    ${this.escapeHtml(task.title)}
                </span>
                <span class="priority-badge">${this.getPriorityLabel(task.priority)}</span>
                <button onclick="app.deleteTask(${task.id})" class="delete">🗑️</button>
            </li>
        `).join('');
    }

    getPriorityLabel(priority) {
        const labels = { high: 'عالية', medium: 'متوسطة', low: 'منخفضة' };
        return labels[priority] || priority;
    }

    escapeHtml(text) {
        const div = document.createElement('div');
        div.textContent = text;
        return div.innerHTML;
    }

    startEdit(id) {
        const task = this.tasks.find(t => t.id === id);
        if (!task) return;
        const newTitle = prompt('تعديل المهمة:', task.title);
        if (newTitle && newTitle.trim()) {
            this.editTask(id, newTitle.trim());
        }
    }

    bindEvents() {
        document.getElementById('addBtn').addEventListener('click', () => {
            const input = document.getElementById('taskInput');
            const priority = document.getElementById('prioritySelect').value;
            if (input.value.trim()) {
                this.addTask(input.value.trim(), priority);
                input.value = '';
            }
        });

        document.getElementById('taskInput').addEventListener('keypress', (e) => {
            if (e.key === 'Enter') document.getElementById('addBtn').click();
        });

        document.querySelectorAll('.filter-btn').forEach(btn => {
            btn.addEventListener('click', () => {
                document.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
                btn.classList.add('active');
                this.filter = btn.dataset.filter;
                this.render();
            });
        });
    }
}

