import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

class Account {
    private String owner;
    private double balance;

    public Account(String owner, double initialBalance) {
        this.owner = owner;
        this.balance = initialBalance;
    }

    public void deposit(double amount) {
        if (amount > 0) balance += amount;
    }

    public void withdraw(double amount) {
        if (amount > 0 && amount <= balance) balance -= amount;
        else System.out.println("رصيد غير كافٍ");
    }

    public double getBalance() { return balance; }
    public String getOwner() { return owner; }
}

public class BankSystem {
    public static void main(String[] args) {
        List<Account> accounts = new ArrayList<>();
        Scanner scanner = new Scanner(System.in);
        while (true) {
            System.out.println("1. إنشاء حساب\n2. إيداع\n3. سحب\n4. عرض\n5. خروج");
            int choice = scanner.nextInt();
            scanner.nextLine();
            switch (choice) {
                case 1:
                    System.out.print("اسم المالك: ");
                    String name = scanner.nextLine();
                    System.out.print("الرصيد الابتدائي: ");
                    double bal = scanner.nextDouble();
                    accounts.add(new Account(name, bal));
                    break;
                case 2:
                    System.out.print("رقم الحساب: ");
                    int idx = scanner.nextInt() - 1;
                    if (idx >= 0 && idx < accounts.size()) {
                        System.out.print("المبلغ: ");
                        accounts.get(idx).deposit(scanner.nextDouble());
                    }
                    break;
                case 3:
                    System.out.print("رقم الحساب: ");
                    idx = scanner.nextInt() - 1;
                    if (idx >= 0 && idx < accounts.size()) {
                        System.out.print("المبلغ: ");
                        accounts.get(idx).withdraw(scanner.nextDouble());
                    }
                    break;
                case 4:
                    for (int i = 0; i < accounts.size(); i++) {
                        System.out.println((i+1) + ". " + accounts.get(i).getOwner() + " - " + accounts.get(i).getBalance());
                    }
                    break;
                case 5:
                    return;
            }
        }
    }
}

import java.util.*;
import java.util.stream.Collectors;
import java.time.LocalDate;
import java.time.Period;

// واجهة قابلة للدفع
interface Payable {
    double calculateSalary();
    String getPaymentDetails();
}

// واجهة قابلة للتقييم
interface Evaluable {
    void addEvaluation(String reviewer, int score, String comment);
    double getAverageScore();
}

// فئة أساسية مجردة
abstract class Employee implements Payable, Evaluable, Comparable<Employee> {
    private static int counter = 1000;
    protected final int id;
    protected String name;
    protected String email;
    protected LocalDate hireDate;
    protected double baseSalary;
    protected List<Evaluation> evaluations = new ArrayList<>();

    public Employee(String name, String email, double baseSalary, LocalDate hireDate) {
        this.id = ++counter;
        this.name = name;
        this.email = email;
        this.baseSalary = baseSalary;
        this.hireDate = hireDate;
    }

    public int getId() { return id; }
    public String getName() { return name; }
    public double getBaseSalary() { return baseSalary; }

    public int getYearsOfService() {
        return Period.between(hireDate, LocalDate.now()).getYears();
    }

    public void addEvaluation(String reviewer, int score, String comment) {
        evaluations.add(new Evaluation(reviewer, score, comment));
    }

    public double getAverageScore() {
        if (evaluations.isEmpty()) return 0;
        return evaluations.stream().mapToInt(Evaluation::getScore).average().orElse(0);
    }

    @Override
    public int compareTo(Employee other) {
        return Double.compare(other.calculateSalary(), this.calculateSalary());
    }

    @Override
    public String toString() {
        return String.format("%d | %s | %s | راتب: %.2f | خدمة: %d سنة | تقييم: %.1f",
                id, name, email, calculateSalary(), getYearsOfService(), getAverageScore());
    }
}

// فئة التقييم
class Evaluation {
    private final String reviewer;
    private final int score;
    private final String comment;
    private final LocalDate date;

    public Evaluation(String reviewer, int score, String comment) {
        if (score < 1 || score > 10)
            throw new IllegalArgumentException("التقييم يجب أن يكون بين 1 و 10");
        this.reviewer = reviewer;
        this.score = score;
        this.comment = comment;
        this.date = LocalDate.now();
    }

    public int getScore() { return score; }
    public String getReviewer() { return reviewer; }
}

// موظف بدوام كامل
class FullTimeEmployee extends Employee {
    private double bonus;

    public FullTimeEmployee(String name, String email, double baseSalary, LocalDate hireDate, double bonus) {
        super(name, email, baseSalary, hireDate);
        this.bonus = bonus;
    }

    @Override
    public double calculateSalary() {
        return baseSalary + bonus + (getYearsOfService() * 100);
    }

    @Override
    public String getPaymentDetails() {
        return String.format("دوام كامل: أساسي %.2f + مكافأة %.2f + أقدمية %.2f",
                baseSalary, bonus, getYearsOfService() * 100.0);
    }
}

// موظف بالساعة
class HourlyEmployee extends Employee {
    private double hourlyRate;
    private int hoursWorked;

    public HourlyEmployee(String name, String email, double hourlyRate, LocalDate hireDate) {
        super(name, email, 0, hireDate);
        this.hourlyRate = hourlyRate;
        this.hoursWorked = 0;
    }

    public void logHours(int hours) {
        if (hours < 0) throw new IllegalArgumentException("الساعات لا يمكن أن تكون سالبة");
        this.hoursWorked += hours;
    }

    @Override
    public double calculateSalary() {
        double regular = Math.min(hoursWorked, 160) * hourlyRate;
        double overtime = Math.max(0, hoursWorked - 160) * hourlyRate * 1.5;
        return regular + overtime;
    }

    @Override
    public String getPaymentDetails() {
        return String.format("بالساعة: %d ساعة × %.2f", hoursWorked, hourlyRate);
    }
}

// موظف بعمولة
class CommissionEmployee extends Employee {
    private double commissionRate;
    private double salesAmount;

    public CommissionEmployee(String name, String email, double baseSalary, LocalDate hireDate, double commissionRate) {
        super(name, email, baseSalary, hireDate);
        this.commissionRate = commissionRate;
        this.salesAmount = 0;
    }

    public void addSale(double amount) {
        if (amount <= 0) throw new IllegalArgumentException("المبلغ يجب أن يكون موجباً");
        this.salesAmount += amount;
    }

    @Override
    public double calculateSalary() {
        return baseSalary + (salesAmount * commissionRate);
    }

    @Override
    public String getPaymentDetails() {
        return String.format("بعمولة: أساسي %.2f + عمولة %.2f%% من %.2f",
                baseSalary, commissionRate * 100, salesAmount);
    }
}

// نظام إدارة الموظفين
class EmployeeManager {
    private final List<Employee> employees = new ArrayList<>();

    public void addEmployee(Employee emp) {
        employees.add(emp);
        System.out.println("✓ تمت إضافة: " + emp.getName());
    }

    public void removeEmployee(int id) {
        employees.removeIf(e -> e.getId() == id);
        System.out.println("✓ تم الحذف");
    }

    public Optional<Employee> findById(int id) {
        return employees.stream().filter(e -> e.getId() == id).findFirst();
    }

    public List<Employee> getTopPerformers(int count) {
        return employees.stream()
                .sorted(Comparator.comparingDouble(Employee::getAverageScore).reversed())
                .limit(count)
                .collect(Collectors.toList());
    }

    public void printAll() {
        employees.stream()
                .sorted()
                .forEach(System.out::println);
    }

    public double getTotalPayroll() {
        return employees.stream().mapToDouble(Employee::calculateSalary).sum();
    }

    public Map<String, Double> getSalariesByType() {
        return employees.stream().collect(Collectors.groupingBy(
                e -> e.getClass().getSimpleName(),
                Collectors.summingDouble(Employee::calculateSalary)
        ));
    }

    public void printStatistics() {
        DoubleSummaryStatistics stats = employees.stream()
                .mapToDouble(Employee::calculateSalary)
                .summaryStatistics();
        System.out.println("\n=== إحصائيات ===");
        System.out.printf("عدد الموظفين: %d%n", stats.getCount());
        System.out.printf("إجمالي الرواتب: %.2f%n", stats.getSum());
        System.out.printf("المتوسط: %.2f%n", stats.getAverage());
        System.out.printf("الأعلى: %.2f%n", stats.getMax());
        System.out.printf("الأدنى: %.2f%n", stats.getMin());
    }
}

