public class EmployeeSystem {
    public static void main(String[] args) {
        EmployeeManager manager = new EmployeeManager();
        Scanner sc = new Scanner(System.in);

        // إضافة بيانات تجريبية
        manager.addEmployee(new FullTimeEmployee("أحمد محمد", "ahmed@co.com", 5000, LocalDate.of(2019, 3, 15), 1000));
        manager.addEmployee(new HourlyEmployee("سارة علي", "sara@co.com", 50, LocalDate.of(2022, 6, 1)));
        manager.addEmployee(new CommissionEmployee("خالد عمر", "khaled@co.com", 3000, LocalDate.of(2021, 1, 10), 0.05));

        while (true) {
            System.out.println("\n=== نظام إدارة الموظفين ===");
            System.out.println("1. إضافة موظف");
            System.out.println("2. عرض الكل");
            System.out.println("3. بحث");
            System.out.println("4. إحصائيات");
            System.out.println("5. أفضل الموظفين");
            System.out.println("6. خروج");
            System.out.print("اختر: ");

            try {
                int choice = Integer.parseInt(sc.nextLine());
                switch (choice) {
                    case 1 -> addEmployeeInteractive(manager, sc);
                    case 2 -> manager.printAll();
                    case 3 -> {
                        System.out.print("الرقم: ");
