                        manager.findById(id).ifPresentOrElse(
                            System.out::println,
                            () -> System.out.println("غير موجود")
                        );
                    }
                    case 4 -> manager.printStatistics();
                    case 5 -> manager.getTopPerformers(3).forEach(System.out::println);
                    case 6 -> { return; }
                    default -> System.out.println("اختيار خاطئ");
                }
            } catch (NumberFormatException e) {
                System.out.println("✗ الرجاء إدخال رقم صحيح");
            } catch (Exception e) {
                System.out.println("✗ خطأ: " + e.getMessage());
