// ===== فئة التاريخ =====
class Date {
    int day, month, year;
public:
    Date(int d = 1, int m = 1, int y = 2025) : day(d), month(m), year(y) {}

    static Date today() {
        time_t t = time(nullptr);
        tm* now = localtime(&t);
        return Date(now->tm_mday, now->tm_mon + 1, now->tm_year + 1900);
    }

    Date addDays(int days) const {
        // تبسيط: إضافة الأيام
        int totalDays = day + days;
        int newMonth = month, newYear = year;
        int daysInMonth[] = {31,28,31,30,31,30,31,31,30,31,30,31};
        while (totalDays > daysInMonth[newMonth-1]) {
            totalDays -= daysInMonth[newMonth-1];
            newMonth++;
            if (newMonth > 12) { newMonth = 1; newYear++; }
        }
        return Date(totalDays, newMonth, newYear);
    }

    bool isBefore(const Date& other) const {
        if (year != other.year) return year < other.year;
        if (month != other.month) return month < other.month;
        return day < other.day;
    }

    string toString() const {
        ostringstream oss;
        oss << setfill('0') << setw(2) << day << "/" << setw(2) << month << "/" << year;
        return oss.str();
    }
};

// ===== فئة أساسية للعناصر =====
class LibraryItem {
protected:
    static int nextId;
    int id;
    string title;
    string author;
    int year;
    bool available;
    int borrowCount;

public:
    LibraryItem(const string& t, const string& a, int y)
        : id(++nextId), title(t), author(a), year(y), available(true), borrowCount(0) {}

    virtual ~LibraryItem() = default;

    int getId() const { return id; }
    string getTitle() const { return title; }
    string getAuthor() const { return author; }
    bool isAvailable() const { return available; }
    int getBorrowCount() const { return borrowCount; }

    void setAvailable(bool a) { available = a; }
    void incrementBorrow() { borrowCount++; }

    virtual string getType() const = 0;
    virtual double getFine(int daysLate) const = 0;
    virtual string toString() const {
        ostringstream oss;
        oss << "[" << getType() << "] #" << id << " - " << title
            << " | " << author << " (" << year << ")"
            << " | " << (available ? "متاح" : "معار")
            << " | مرات الاستعارة: " << borrowCount;
        return oss.str();
    }

    bool operator<(const LibraryItem& other) const {
        return borrowCount > other.borrowCount; // الأكثر استعارة أولاً
    }
};

int LibraryItem::nextId = 0;

