// ===== العضو =====
class Member {
    int id;
    string name;
    string email;
    vector<int> borrowedItems;
    double totalFines;

public:
    Member(int i, const string& n, const string& e)
        : id(i), name(n), email(e), totalFines(0) {}

    int getId() const { return id; }
    string getName() const { return name; }
    double getTotalFines() const { return totalFines; }
    const vector<int>& getBorrowedItems() const { return borrowedItems; }

    void borrowItem(int itemId) { borrowedItems.push_back(itemId); }
    void returnItem(int itemId) {
        borrowedItems.erase(remove(borrowedItems.begin(), borrowedItems.end(), itemId), borrowedItems.end());
    }
    void addFine(double amount) { totalFines += amount; }
    void payFine(double amount) { totalFines = max(0.0, totalFines - amount); }

    string toString() const {
        ostringstream oss;
        oss << "عضو #" << id << " - " << name << " (" << email << ")"
            << " | كتب معارة: " << borrowedItems.size()
            << " | غرامات: " << fixed << setprecision(2) << totalFines;
        return oss.str();
    }
};

// ===== سجل الإعارة =====
struct LoanRecord {
    int itemId;
    int memberId;
    Date borrowDate;
    Date dueDate;
    Date returnDate;
    bool returned;
};

// ===== نظام المكتبة =====
class LibrarySystem {
    vector<unique_ptr<LibraryItem>> items;
    vector<Member> members;
    vector<LoanRecord> loans;
    int nextMemberId;

public:
    LibrarySystem() : nextMemberId(1) {}

    // إضافة عنصر (template)
    template<typename T, typename... Args>
    void addItem(Args&&... args) {
        items.push_back(make_unique<T>(forward<Args>(args)...));
        cout << "✓ تمت الإضافة: " << items.back()->getTitle() << endl;
    }

    void addMember(const string& name, const string& email) {
        members.emplace_back(nextMemberId++, name, email);
        cout << "✓ تمت إضافة العضو: " << name << endl;
    }

    LibraryItem* findItem(int id) {
        for (auto& item : items)
            if (item->getId() == id) return item.get();
        return nullptr;
    }

    Member* findMember(int id) {
        for (auto& m : members)
            if (m.getId() == id) return &m;
        return nullptr;
    }

    bool borrowItem(int itemId, int memberId, int days = 14) {
        auto* item = findItem(itemId);
        auto* member = findMember(memberId);

        if (!item) { cout << "✗ العنصر غير موجود\n"; return false; }
        if (!member) { cout << "✗ العضو غير موجود\n"; return false; }
        if (!item->isAvailable()) { cout << "✗ العنصر غير متاح\n"; return false; }

        item->setAvailable(false);
        item->incrementBorrow();
        member->borrowItem(itemId);

        LoanRecord loan;
        loan.itemId = itemId;
        loan.memberId = memberId;
        loan.borrowDate = Date::today();
        loan.dueDate = loan.borrowDate.addDays(days);
        loan.returned = false;
        loans.push_back(loan);

        cout << "✓ تمت الاستعارة. تاريخ الإرجاع: " << loan.dueDate.toString() << endl;
        return true;
    }

    bool returnItem(int itemId, int memberId) {
        auto* item = findItem(itemId);
        auto* member = findMember(memberId);
        if (!item || !member) { cout << "✗ بيانات غير صحيحة\n"; return false; }

        Date today = Date::today();
        for (auto& loan : loans) {
            if (loan.itemId == itemId && loan.memberId == memberId && !loan.returned) {
                loan.returned = true;
                loan.returnDate = today;
                item->setAvailable(true);
                member->returnItem(itemId);

                if (loan.dueDate.isBefore(today)) {
                    // حساب الأيام المتأخرة (تبسيط)
                    int daysLate = 7; // يمكن حسابها بدقة
                    double fine = item->getFine(daysLate);
                    member->addFine(fine);
                    cout << "⚠ متأخر! غرامة: " << fixed << setprecision(2) << fine << " ر.س\n";
                }
                cout << "✓ تم الإرجاع بنجاح\n";
                return true;
            }
        }
        cout << "✗ لا يوجد سجل إعارة\n";
        return false;
    }

    // توصيات ذكية: العناصر الأكثر استعارة
    vector<LibraryItem*> getRecommendations(int count = 5) {
        vector<LibraryItem*> result;
        vector<LibraryItem*> sorted;
        for (auto& item : items) sorted.push_back(item.get());
        sort(sorted.begin(), sorted.end(), [](auto* a, auto* b) {
            return *a < *b;
        });
        for (int i = 0; i < min(count, (int)sorted.size()); i++)
            result.push_back(sorted[i]);
        return result;
    }

    // البحث المتقدم
    template<typename Predicate>
    vector<LibraryItem*> search(Predicate pred) {
        vector<LibraryItem*> result;
        for (auto& item : items)
            if (pred(*item)) result.push_back(item.get());
        return result;
    }

    void printAllItems() const {
        cout << "\n=== جميع العناصر (" << items.size() << ") ===\n";
        for (const auto& item : items)
            cout << item->toString() << "\n";
    }

    void printAllMembers() const {
        cout << "\n=== الأعضاء (" << members.size() << ") ===\n";
        for (const auto& m : members)
            cout << m.toString() << "\n";
    }

    void printStatistics() const {
        cout << "\n=== الإحصائيات ===\n";
        cout << "عدد العناصر: " << items.size() << "\n";
        cout << "عدد الأعضاء: " << members.size() << "\n";
        cout << "عدد الإعارات: " << loans.size() << "\n";

        int available = 0, borrowed = 0;
        for (const auto& item : items)
            item->isAvailable() ? available++ : borrowed++;
        cout << "متاح: " << available << " | معار: " << borrowed << "\n";

        double totalFines = 0;
        for (const auto& m : members) totalFines += m.getTotalFines();
        cout << "إجمالي الغرامات: " << fixed << setprecision(2) << totalFines << " ر.س\n";
    }
};

