        var tasks = new List<Task>();
        while (true) {
            Console.WriteLine("\n1. إضافة مهمة\n2. عرض المهام\n3. إنجاز مهمة\n4. خروج");
            Console.Write("اختر: ");
            var choice = Console.ReadLine();
            switch (choice) {
                case "1":
                    Console.Write("عنوان المهمة: ");
                    tasks.Add(new Task { Title = Console.ReadLine(), IsDone = false });
                    break;
                case "2":
                    for (int i = 0; i < tasks.Count; i++) {
                        var status = tasks[i].IsDone ? "✓" : "✗";
                        Console.WriteLine($"{i + 1}. [{status}] {tasks[i].Title}");
                    }
                    break;
                case "3":
                    Console.Write("رقم المهمة: ");
                    if (int.TryParse(Console.ReadLine(), out int idx) && idx > 0 && idx <= tasks.Count) {
                        tasks[idx - 1].IsDone = true;
                    }
                    break;
                case "4":
                    return;
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

namespace ECommerceSystem
{
    // ===== النماذج =====
    public class Product
    {
        public int Id { get; set; }
        public string Name { get; set; }
        public string Category { get; set; }
        public decimal Price { get; set; }
        public int Stock { get; set; }
        public double Rating { get; set; }

        public bool InStock => Stock > 0;
        public override string ToString() => $"#{Id} {Name} ({Category}) - {Price:C} | مخزون: {Stock} | تقييم: {Rating:F1}";
    }

    public class Customer
    {
        public int Id { get; set; }
        public string Name { get; set; }
        public string Email { get; set; }
        public string City { get; set; }
        public DateTime RegisteredAt { get; set; }
        public List<Order> Orders { get; set; } = new();

        public decimal TotalSpent => Orders.Sum(o => o.Total);
        public override string ToString() => $"#{Id} {Name} ({Email}) - {City} | مشتريات: {TotalSpent:C}";
    }

    public class OrderItem
    {
        public Product Product { get; set; }
        public int Quantity { get; set; }
        public decimal Subtotal => Product.Price * Quantity;
    }

    public class Order
    {
        public int Id { get; set; }
        public Customer Customer { get; set; }
        public List<OrderItem> Items { get; set; } = new();
        public DateTime OrderDate { get; set; }
        public OrderStatus Status { get; set; }

        public decimal Total => Items.Sum(i => i.Subtotal);
        public int ItemCount => Items.Sum(i => i.Quantity);

        public override string ToString()
        {
            var sb = new StringBuilder();
            sb.AppendLine($"طلب #{Id} - {Customer.Name} - {OrderDate:yyyy-MM-dd} [{Status}]");
            foreach (var item in Items)
                sb.AppendLine($"  - {item.Product.Name} × {item.Quantity} = {item.Subtotal:C}");
            sb.AppendLine($"  الإجمالي: {Total:C}");
            return sb.ToString();
        }
    }

    public enum OrderStatus { Pending, Processing, Shipped, Delivered, Cancelled }

    // ===== خدمة التجارة الإلكترونية =====
    public class ECommerceService
    {
        private List<Product> _products = new();
        private List<Customer> _customers = new();
        private List<Order> _orders = new();
        private int _nextOrderId = 1;

        // إدارة المنتجات
        public void AddProduct(Product p) { _products.Add(p); }

        public IEnumerable<Product> SearchProducts(string query) =>
            _products.Where(p => p.Name.Contains(query, StringComparison.OrdinalIgnoreCase) ||
                                 p.Category.Contains(query, StringComparison.OrdinalIgnoreCase));

        public IEnumerable<Product> GetTopRated(int count) =>
            _products.OrderByDescending(p => p.Rating).Take(count);

        // إدارة العملاء
        public void AddCustomer(Customer c) { _customers.Add(c); }

        // إنشاء طلب
        public Order CreateOrder(int customerId, params (int productId, int qty)[] items)
        {
            var customer = _customers.FirstOrDefault(c => c.Id == customerId)
                ?? throw new Exception("العميل غير موجود");

            var order = new Order
            {
                Id = _nextOrderId++,
                Customer = customer,
                OrderDate = DateTime.Now,
                Status = OrderStatus.Pending
            };

            foreach (var (productId, qty) in items)
            {
                var product = _products.FirstOrDefault(p => p.Id == productId)
                    ?? throw new Exception($"المنتج {productId} غير موجود");

                if (product.Stock < qty)
                    throw new Exception($"مخزون {product.Name} غير كافٍ (متاح: {product.Stock})");

                product.Stock -= qty;
                order.Items.Add(new OrderItem { Product = product, Quantity = qty });
            }

            customer.Orders.Add(order);
            _orders.Add(order);
            Console.WriteLine($"✓ تم إنشاء الطلب #{order.Id} بإجمالي {order.Total:C}");
            return order;
        }

        // تحديث حالة الطلب
        public void UpdateOrderStatus(int orderId, OrderStatus newStatus)
        {
            var order = _orders.FirstOrDefault(o => o.Id == orderId)
                ?? throw new Exception("الطلب غير موجود");
            order.Status = newStatus;
            Console.WriteLine($"✓ الطلب #{orderId} → {newStatus}");
        }

        // ===== تقارير باستخدام LINQ =====
        public void PrintSalesReport()
        {
            Console.WriteLine("\n=== تقرير المبيعات ===");
            Console.WriteLine($"إجمالي الطلبات: {_orders.Count}");
            Console.WriteLine($"إجمالي الإيرادات: {_orders.Sum(o => o.Total):C}");
            Console.WriteLine($"متوسط قيمة الطلب: {_orders.Average(o => o.Total):C}");

            Console.WriteLine("\nالمبيعات حسب الفئة:");
            var byCategory = _orders
                .SelectMany(o => o.Items)
                .GroupBy(i => i.Product.Category)
                .Select(g => new
                {
                    Category = g.Key,
                    Revenue = g.Sum(i => i.Subtotal),
                    UnitsSold = g.Sum(i => i.Quantity)
                })
                .OrderByDescending(x => x.Revenue);

            foreach (var cat in byCategory)
                Console.WriteLine($"  {cat.Category}: {cat.Revenue:C} ({cat.UnitsSold} وحدة)");

            Console.WriteLine("\nأفضل 5 عملاء:");
            _customers
                .OrderByDescending(c => c.TotalSpent)
                .Take(5)
                .ToList()
                .ForEach(c => Console.WriteLine($"  {c.Name}: {c.TotalSpent:C}"));

            Console.WriteLine("\nالمنتجات الأكثر مبيعاً:");
            var topProducts = _orders
                .SelectMany(o => o.Items)
                .GroupBy(i => i.Product.Name)
                .Select(g => new { Name = g.Key, Qty = g.Sum(i => i.Quantity), Rev = g.Sum(i => i.Subtotal) })
                .OrderByDescending(x => x.Qty)
                .Take(5);

            foreach (var p in topProducts)
                Console.WriteLine($"  {p.Name}: {p.Qty} وحدة ({p.Rev:C})");
        }

        // إحصائيات متقدمة
        public void PrintAdvancedStats()
        {
            Console.WriteLine("\n=== إحصائيات متقدمة ===");

            // معدل الشراء لكل مدينة
