// ===== الأنواع الأساسية =====
type UUID = string;
type ISODate = string;

type Priority = 'low' | 'medium' | 'high' | 'critical';
type Status = 'todo' | 'in-progress' | 'review' | 'done';

interface BaseEntity {
    id: UUID;
    createdAt: ISODate;
    updatedAt: ISODate;
}

interface User extends BaseEntity {
    name: string;
    email: string;
    role: UserRole;
    avatar?: string;
}

type UserRole = 'admin' | 'manager' | 'member' | 'viewer';

interface Task extends BaseEntity {
    title: string;
    description: string;
    status: Status;
    priority: Priority;
    assigneeId: UUID | null;
    projectId: UUID;
    dueDate: ISODate | null;
    tags: string[];
    subtasks: Subtask[];
    attachments: Attachment[];
}

interface Subtask {
    id: UUID;
    title: string;
    completed: boolean;
}

interface Attachment {
    id: UUID;
    name: string;
    url: string;
    size: number;
    type: string;
}

interface Project extends BaseEntity {
    name: string;
    description: string;
    ownerId: UUID;
    memberIds: UUID[];
    taskIds: UUID[];
}

// ===== Generic Repository =====
interface Repository<T extends BaseEntity> {
    getAll(): Promise<T[]>;
    getById(id: UUID): Promise<T | null>;
    create(data: Omit<T, keyof BaseEntity>): Promise<T>;
    update(id: UUID, data: Partial<T>): Promise<T>;
    delete(id: UUID): Promise<boolean>;
}

class InMemoryRepository<T extends BaseEntity> implements Repository<T> {
    private items = new Map<UUID, T>();

    async getAll(): Promise<T[]> {
        return Array.from(this.items.values());
    }

    async getById(id: UUID): Promise<T | null> {
        return this.items.get(id) ?? null;
    }

    async create(data: Omit<T, keyof BaseEntity>): Promise<T> {
        const now = new Date().toISOString();
        const item = {
            ...data,
            id: crypto.randomUUID(),
            createdAt: now,
            updatedAt: now,
        } as T;
        this.items.set(item.id, item);
        return item;
    }

    async update(id: UUID, data: Partial<T>): Promise<T> {
        const existing = this.items.get(id);
        if (!existing) throw new Error(`العنصر ${id} غير موجود`);
        const updated = {
            ...existing,
            ...data,
            id,
            updatedAt: new Date().toISOString(),
        } as T;
        this.items.set(id, updated);
        return updated;
    }

    async delete(id: UUID): Promise<boolean> {
        return this.items.delete(id);
    }
}

// ===== نظام إدارة المهام =====
type EventType = 'created' | 'updated' | 'deleted';
interface TaskEvent {
    type: EventType;
    taskId: UUID;
    timestamp: ISODate;
    data?: Partial<Task>;
}

class TaskManager {
    private taskRepo = new InMemoryRepository<Task>();
    private listeners: ((event: TaskEvent) => void)[] = [];

    onEvent(listener: (event: TaskEvent) => void): () => void {
        this.listeners.push(listener);
        return () => {
            this.listeners = this.listeners.filter(l => l !== listener);
        };
    }

    private emit(event: TaskEvent): void {
        this.listeners.forEach(l => l(event));
    }

    async createTask(data: Omit<Task, keyof BaseEntity | 'subtasks' | 'attachments'>): Promise<Task> {
        const task = await this.taskRepo.create({
            ...data,
            subtasks: [],
            attachments: [],
        });
        this.emit({ type: 'created', taskId: task.id, timestamp: task.createdAt });
        return task;
    }

    async updateTask(id: UUID, data: Partial<Task>): Promise<Task> {
        const task = await this.taskRepo.update(id, data);
        this.emit({ type: 'updated', taskId: id, timestamp: task.updatedAt, data });
        return task;
    }

    async addSubtask(taskId: UUID, title: string): Promise<Task> {
        const task = await this.taskRepo.getById(taskId);
        if (!task) throw new Error('المهمة غير موجودة');
        task.subtasks.push({ id: crypto.randomUUID(), title, completed: false });
        return this.updateTask(taskId, { subtasks: task.subtasks });
    }

    async toggleSubtask(taskId: UUID, subtaskId: UUID): Promise<Task> {
        const task = await this.taskRepo.getById(taskId);
        if (!task) throw new Error('المهمة غير موجودة');
        const subtask = task.subtasks.find(s => s.id === subtaskId);
        if (subtask) subtask.completed = !subtask.completed;
        return this.updateTask(taskId, { subtasks: task.subtasks });
    }

    async getAllTasks(): Promise<Task[]> {
        return this.taskRepo.getAll();
    }

    // فلترة متقدمة
    async filterTasks(filter: {
        status?: Status[];
        priority?: Priority[];
        assigneeId?: UUID;
        search?: string;
        dueBefore?: ISODate;
        tags?: string[];
    }): Promise<Task[]> {
        let tasks = await this.getAllTasks();

        if (filter.status?.length)
            tasks = tasks.filter(t => filter.status!.includes(t.status));
        if (filter.priority?.length)
            tasks = tasks.filter(t => filter.priority!.includes(t.priority));
        if (filter.assigneeId)
            tasks = tasks.filter(t => t.assigneeId === filter.assigneeId);
        if (filter.search)
            tasks = tasks.filter(t =>
                t.title.toLowerCase().includes(filter.search!.toLowerCase()) ||
                t.description.toLowerCase().includes(filter.search!.toLowerCase())
            );
        if (filter.dueBefore)
            tasks = tasks.filter(t => t.dueDate && t.dueDate <= filter.dueBefore!);
        if (filter.tags?.length)
            tasks = tasks.filter(t => filter.tags!.some(tag => t.tags.includes(tag)));

        return tasks;
    }

    // إحصائيات
    async getStats(): Promise<{
        total: number;
        byStatus: Record<Status, number>;
        byPriority: Record<Priority, number>;
        overdue: number;
        completedThisWeek: number;
    }> {
        const tasks = await this.getAllTasks();
        const now = new Date();
        const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000).toISOString();

        const byStatus = tasks.reduce((acc, t) => {
            acc[t.status] = (acc[t.status] || 0) + 1;
            return acc;
        }, {} as Record<Status, number>);

        const byPriority = tasks.reduce((acc, t) => {
            acc[t.priority] = (acc[t.priority] || 0) + 1;
            return acc;
        }, {} as Record<Priority, number>);

        return {
            total: tasks.length,
            byStatus,
            byPriority,
            overdue: tasks.filter(t =>
                t.dueDate && t.dueDate < now.toISOString() && t.status !== 'done'
            ).length,
            completedThisWeek: tasks.filter(t =>
                t.status === 'done' && t.updatedAt >= weekAgo
            ).length,
        };
    }
}

