type Task struct {
    ID          string    `json:"id"`
    Title       string    `json:"title"`
    Description string    `json:"description"`
    Priority    Priority  `json:"priority"`
    Status      Status    `json:"status"`
    Tags        []string  `json:"tags"`
    DueDate     time.Time `json:"due_date"`
    CreatedAt   time.Time `json:"created_at"`
    UpdatedAt   time.Time `json:"updated_at"`
}

type TaskFilter struct {
    Status   *Status
    Priority *Priority
    Tag      string
    Search   string
}

// ===== الأخطاء =====
var (
    ErrNotFound     = errors.New("المهمة غير موجودة")
    ErrInvalidInput = errors.New("مدخلات غير صحيحة")
)

// ===== إدارة المهام =====
type TaskManager struct {
    mu    sync.RWMutex
    tasks map[string]*Task
    events chan TaskEvent
}

type TaskEvent struct {
    Type   string
    TaskID string
    Task   *Task
}

func NewTaskManager() *TaskManager {
    tm := &TaskManager{
        tasks:  make(map[string]*Task),
        events: make(chan TaskEvent, 100),
    }
    go tm.eventLogger()
    return tm
}

func (tm *TaskManager) eventLogger() {
    for event := range tm.events {
        log.Printf("[حدث] %s - المهمة: %s\n", event.Type, event.TaskID)
    }
}

func (tm *TaskManager) Create(title, description string, priority Priority, tags []string, dueDate time.Time) (*Task, error) {
    if strings.TrimSpace(title) == "" {
        return nil, ErrInvalidInput
    }

    tm.mu.Lock()
    defer tm.mu.Unlock()

    task := &Task{
        ID:          generateID(),
        Title:       title,
        Description: description,
        Priority:    priority,
        Status:      Todo,
        Tags:        tags,
        DueDate:     dueDate,
        CreatedAt:   time.Now(),
        UpdatedAt:   time.Now(),
    }

    tm.tasks[task.ID] = task
    tm.events <- TaskEvent{Type: "إنشاء", TaskID: task.ID, Task: task}
    return task, nil
}

func (tm *TaskManager) Get(id string) (*Task, error) {
    tm.mu.RLock()
    defer tm.mu.RUnlock()

    task, ok := tm.tasks[id]
    if !ok {
        return nil, ErrNotFound
    }
    return task, nil
}

func (tm *TaskManager) Update(id string, updateFn func(*Task)) (*Task, error) {
    tm.mu.Lock()
    defer tm.mu.Unlock()

    task, ok := tm.tasks[id]
    if !ok {
        return nil, ErrNotFound
    }

    updateFn(task)
    task.UpdatedAt = time.Now()
    tm.events <- TaskEvent{Type: "تحديث", TaskID: id, Task: task}
    return task, nil
}

func (tm *TaskManager) Delete(id string) error {
    tm.mu.Lock()
    defer tm.mu.Unlock()

    if _, ok := tm.tasks[id]; !ok {
        return ErrNotFound
    }
    delete(tm.tasks, id)
    tm.events <- TaskEvent{Type: "حذف", TaskID: id}
    return nil
}

func (tm *TaskManager) List(filter TaskFilter) []*Task {
    tm.mu.RLock()
    defer tm.mu.RUnlock()

    var result []*Task
    for _, task := range tm.tasks {
        if filter.Status != nil && task.Status != *filter.Status {
            continue
        }
        if filter.Priority != nil && task.Priority != *filter.Priority {
            continue
        }
        if filter.Tag != "" && !contains(task.Tags, filter.Tag) {
            continue
        }
        if filter.Search != "" {
            search := strings.ToLower(filter.Search)
            if !strings.Contains(strings.ToLower(task.Title), search) &&
                !strings.Contains(strings.ToLower(task.Description), search) {
                continue
            }
        }
        result = append(result, task)
    }

    sort.Slice(result, func(i, j int) bool {
        if result[i].Priority != result[j].Priority {
            return result[i].Priority > result[j].Priority
        }
        return result[i].DueDate.Before(result[j].DueDate)
    })

    return result
}

func (tm *TaskManager) Stats() map[string]int {
    tm.mu.RLock()
    defer tm.mu.RUnlock()

    stats := map[string]int{
        "total":      len(tm.tasks),
        "todo":       0,
        "in_progress": 0,
        "done":       0,
        "overdue":    0,
    }

    now := time.Now()
    for _, task := range tm.tasks {
        switch task.Status {
        case Todo: stats["todo"]++
        case InProgress: stats["in_progress"]++
        case Done: stats["done"]++
        }
        if task.Status != Done && task.DueDate.Before(now) {
            stats["overdue"]++
        }
    }
    return stats
}

// ===== التخزين في ملف =====
func (tm *TaskManager) SaveToFile(filename string) error {
    tm.mu.RLock()
    defer tm.mu.RUnlock()

    data, err := json.MarshalIndent(tm.tasks, "", "  ")
    if err != nil {
        return err
    }
    return os.WriteFile(filename, data, 0644)
}

func (tm *TaskManager) LoadFromFile(filename string) error {
    tm.mu.Lock()
    defer tm.mu.Unlock()

    data, err := os.ReadFile(filename)
    if err != nil {
        if os.IsNotExist(err) {
            return nil
        }
        return err
    }

    var tasks map[string]*Task
    if err := json.Unmarshal(data, &tasks); err != nil {
        return err
    }
    tm.tasks = tasks
    return nil
}

// ===== المعالجات المتوازية =====
func (tm *TaskManager) ProcessTasksConcurrently(ctx context.Context, ids []string, processFn func(*Task) error) error {
    var wg sync.WaitGroup
    errCh := make(chan error, len(ids))

    for _, id := range ids {
        wg.Add(1)
        go func(taskID string) {
            defer wg.Done()
            select {
            case <-ctx.Done():
                errCh <- ctx.Err()
            default:
                task, err := tm.Get(taskID)
                if err != nil {
                    errCh <- err
                    return
                }
                if err := processFn(task); err != nil {
                    errCh <- err
                }
            }
        }(id)
    }

    go func() {
        wg.Wait()
        close(errCh)
    }()

    var errs []error
    for err := range errCh {
        errs = append(errs, err)
    }

    if len(errs) > 0 {
        return fmt.Errorf("%d أخطاء: %v", len(errs), errs)
    }
    return nil
}

// ===== أدوات مساعدة =====
var idCounter int64
var idMutex sync.Mutex

func generateID() string {
    idMutex.Lock()
    defer idMutex.Unlock()
    idCounter++
    return fmt.Sprintf("TASK-%d-%d", time.Now().Unix(), idCounter)
}

