use std::fs;
use std::io::{self, Write};
use std::path::Path;

#[derive(Debug)]
struct Task {
    title: String,
    done: bool,
}

fn load_tasks(filename: &str) -> Vec<Task> {
    let mut tasks = Vec::new();
    if let Ok(content) = fs::read_to_string(filename) {
        for line in content.lines() {
            let parts: Vec<&str> = line.split('|').collect();
            if parts.len() == 2 {
                tasks.push(Task {
                    title: parts[0].to_string(),
                    done: parts[1] == "1",
                });
            }
        }
    }
    tasks
}

fn save_tasks(filename: &str, tasks: &[Task]) {
    let mut output = String::new();
    for task in tasks {
        output.push_str(&format!("{}|{}\n", task.title, if task.done { 1 } else { 0 }));
    }
    fs::write(filename, output).expect("تعذر الحفظ");
}

fn main() {
    let filename = "tasks.txt";
    let mut tasks = load_tasks(filename);
    loop {
        println!("\n1. إضافة مهمة\n2. عرض المهام\n3. إنجاز مهمة\n4. خروج");
        print!("اختر: ");
        io::stdout().flush().unwrap();
        let mut choice = String::new();
        io::stdin().read_line(&mut choice).unwrap();
        match choice.trim() {
            "1" => {
                print!("عنوان المهمة: ");
                io::stdout().flush().unwrap();
                let mut title = String::new();
                io::stdin().read_line(&mut title).unwrap();
                tasks.push(Task { title: title.trim().to_string(), done: false });
                save_tasks(filename, &tasks);
            }
            "2" => {
                for (i, task) in tasks.iter().enumerate() {
                    let status = if task.done { "✓" } else { "✗" };
                    println!("{}. [{}] {}", i + 1, status, task.title);
                }
            }
            "3" => {
                print!("رقم المهمة: ");
                io::stdout().flush().unwrap();
                let mut idx = String::new();
                io::stdin().read_line(&mut idx).unwrap();
                if let Ok(n) = idx.trim().parse::<usize>() {
                    if n > 0 && n <= tasks.len() {
                        tasks[n - 1].done = true;
                        save_tasks(filename, &tasks);
                    }
                }
            }
            "4" => break,
            _ => println!("اختيار خاطئ"),
        }
    }
}

use std::collections::HashMap;
use std::hash::Hash;
use std::sync::{Arc, Mutex, RwLock};
use std::thread;
use std::time::{Duration, Instant};
use std::fmt::Debug;

// ===== Trait للعناصر القابلة للتخزين =====
pub trait Cacheable: Clone + Send + Sync + 'static {
    fn size_bytes(&self) -> usize;
}

impl Cacheable for String {
    fn size_bytes(&self) -> usize { self.len() }
}

impl Cacheable for Vec<u8> {
    fn size_bytes(&self) -> usize { self.len() }
}

impl Cacheable for i64 {
    fn size_bytes(&self) -> usize { 8 }
}

// ===== Entry =====
#[derive(Debug, Clone)]
struct CacheEntry<V> {
    value: V,
    created_at: Instant,
    ttl: Duration,
    access_count: u64,
    last_accessed: Instant,
}

impl<V: Cacheable> CacheEntry<V> {
    fn new(value: V, ttl: Duration) -> Self {
        let now = Instant::now();
        Self {
            value,
            created_at: now,
            ttl,
            access_count: 0,
            last_accessed: now,
        }
    }

    fn is_expired(&self) -> bool {
        self.created_at.elapsed() > self.ttl
    }

    fn touch(&mut self) {
        self.access_count += 1;
        self.last_accessed = Instant::now();
    }
}

// ===== سياسة الإخلاء =====
#[derive(Debug, Clone, Copy)]
pub enum EvictionPolicy {
    LRU, // الأقل استخداماً مؤخراً
    LFU, // الأقل استخداماً بشكل عام
    FIFO, // الأول دخولاً أول خروجاً
    TTL, // الأقرب للانتهاء
}

// ===== الإحصائيات =====
#[derive(Debug, Default, Clone)]
pub struct CacheStats {
    pub hits: u64,
    pub misses: u64,
    pub evictions: u64,
    pub expired: u64,
    pub total_entries: usize,
}

impl CacheStats {
    pub fn hit_rate(&self) -> f64 {
        let total = self.hits + self.misses;
        if total == 0 { 0.0 } else { self.hits as f64 / total as f64 * 100.0 }
    }
}

// ===== التخزين المؤقت =====
pub struct Cache<K, V>
where
    K: Eq + Hash + Clone + Debug,
    V: Cacheable,
{
    inner: RwLock<HashMap<K, CacheEntry<V>>>,
    max_size: usize,
    max_capacity: usize,
    policy: EvictionPolicy,
    stats: Mutex<CacheStats>,
    current_size: Mutex<usize>,
}

impl<K, V> Cache<K, V>
where
    K: Eq + Hash + Clone + Debug,
    V: Cacheable,
{
    pub fn new(max_capacity: usize, policy: EvictionPolicy) -> Self {
        Self {
            inner: RwLock::new(HashMap::new()),
            max_size: max_capacity * 1024, // بالكيلوبايت
            max_capacity,
            policy,
            stats: Mutex::new(CacheStats::default()),
            current_size: Mutex::new(0),
        }
    }

    pub fn insert(&self, key: K, value: V, ttl: Duration) -> Option<V> {
        let size = value.size_bytes();

        // التحقق من الحجم
        {
            let mut current = self.current_size.lock().unwrap();
            if *current + size > self.max_size {
                drop(current);
                self.evict_until_fit(size);
            }
            *current += size;
        }

        let entry = CacheEntry::new(value, ttl);
        let mut map = self.inner.write().unwrap();

        // التحقق من السعة
        if map.len() >= self.max_capacity && !map.contains_key(&key) {
            drop(map);
            self.evict_one();
            map = self.inner.write().unwrap();
        }

        let old = map.insert(key.clone(), entry);
        if let Some(ref old_entry) = old {
            let mut current = self.current_size.lock().unwrap();
            *current = current.saturating_sub(old_entry.value.size_bytes());
        }

        self.update_stats(|s| s.total_entries = map.len());
        old.map(|e| e.value)
    }

    pub fn get(&self, key: &K) -> Option<V> {
        // التحقق من الانتهاء
        {
            let map = self.inner.read().unwrap();
            if let Some(entry) = map.get(key) {
                if entry.is_expired() {
                    drop(map);
                    self.remove(key);
                    self.update_stats(|s| s.expired += 1);
                    self.update_stats(|s| s.misses += 1);
                    return None;
                }
            } else {
                self.update_stats(|s| s.misses += 1);
                return None;
            }
        }

        // تحديث الإحصائيات والإرجاع
        let mut map = self.inner.write().unwrap();
        if let Some(entry) = map.get_mut(key) {
            entry.touch();
            let value = entry.value.clone();
            drop(map);
            self.update_stats(|s| s.hits += 1);
            Some(value)
        } else {
            None
        }
    }

    pub fn remove(&self, key: &K) -> Option<V> {
        let mut map = self.inner.write().unwrap();
        if let Some(entry) = map.remove(key) {
            let mut current = self.current_size.lock().unwrap();
            *current = current.saturating_sub(entry.value.size_bytes());
            Some(entry.value)
        } else {
            None
        }
    }

    pub fn contains(&self, key: &K) -> bool {
        let map = self.inner.read().unwrap();
        map.get(key).map_or(false, |e| !e.is_expired())
    }

    pub fn clear(&self) {
        let mut map = self.inner.write().unwrap();
        map.clear();
        let mut current = self.current_size.lock().unwrap();
        *current = 0;
    }

    pub fn len(&self) -> usize {
        self.inner.read().unwrap().len()
    }

    pub fn is_empty(&self) -> bool {
        self.len() == 0
    }

    pub fn cleanup_expired(&self) -> usize {
        let mut map = self.inner.write().unwrap();
        let expired_keys: Vec<K> = map
            .iter()
            .filter(|(_, e)| e.is_expired())
            .map(|(k, _)| k.clone())
            .collect();

        let count = expired_keys.len();
        for key in expired_keys {
            map.remove(&key);
        }

        if count > 0 {
            self.update_stats(|s| s.expired += count as u64);
        }
        count
    }

    pub fn stats(&self) -> CacheStats {
        let stats = self.stats.lock().unwrap().clone();
        let total = self.len();
        CacheStats { total_entries: total, ..stats }
    }

    fn evict_one(&self) {
        let mut map = self.inner.write().unwrap();
        let key_to_evict = match self.policy {
            EvictionPolicy::LRU => map
                .iter()
                .min_by_key(|(_, e)| e.last_accessed)
                .map(|(k, _)| k.clone()),
            EvictionPolicy::LFU => map
                .iter()
                .min_by_key(|(_, e)| e.access_count)
                .map(|(k, _)| k.clone()),
            EvictionPolicy::FIFO => map
                .iter()
                .min_by_key(|(_, e)| e.created_at)
                .map(|(k, _)| k.clone()),
            EvictionPolicy::TTL => map
                .iter()
                .min_by_key(|(_, e)| e.created_at + e.ttl)
                .map(|(k, _)| k.clone()),
        };

        if let Some(key) = key_to_evict {
            if let Some(entry) = map.remove(&key) {
                let mut current = self.current_size.lock().unwrap();
                *current = current.saturating_sub(entry.value.size_bytes());
            }
            drop(map);
            self.update_stats(|s| s.evictions += 1);
        }
    }

    fn evict_until_fit(&self, needed: usize) {
        loop {
            let current = *self.current_size.lock().unwrap();
            if current + needed <= self.max_size {
                break;
            }
            self.evict_one();
            if self.is_empty() {
                break;
            }
        }
    }

    fn update_stats<F: FnOnce(&mut CacheStats)>(&self, f: F) {
        let mut stats = self.stats.lock().unwrap();
        f(&mut stats);
    }
}

// ===== مثال الاستخدام =====
fn main() {
    let cache: Arc<Cache<String, String>> = Arc::new(
        Cache::new(100, EvictionPolicy::LRU)
    );

    // إدراج قيم
    cache.insert("user:1".to_string(), "أحمد".to_string(), Duration::from_secs(60));
    cache.insert("user:2".to_string(), "سارة".to_string(), Duration::from_secs(60));
    cache.insert("user:3".to_string(), "خالد".to_string(), Duration::from_secs(60));

    // قراءة
    if let Some(v) = cache.get(&"user:1".to_string()) {
        println!("قيمة user:1 = {}", v);
    }

    // الوصول المتوازي
    let mut handles = vec![];
    for i in 0..10 {
        let c = Arc::clone(&cache);
        handles.push(thread::spawn(move || {
            let key = format!("user:{}", i);
            c.insert(key.clone(), format!("قيمة {}", i), Duration::from_secs(30));
            c.get(&key);
        }));
    }

    for h in handles {
        h.join().unwrap();
    }

    println!("\nعدد العناصر: {}", cache.len());
    let stats = cache.stats();
    println!("إحصائيات: {:?}", stats);
    println!("معدل الإصابات: {:.1}%", stats.hit_rate());

    // تنظيف
    thread::sleep(Duration::from_millis(100));
    let expired = cache.cleanup_expired();
    println!("تم حذف {} عنصر منتهي", expired);
}

