import kotlinx.coroutines.*
import kotlinx.coroutines.flow.*
import java.util.UUID
import java.time.Instant

// ===== النماذج =====
data class User(
    val id: String,
    val name: String,
    val email: String,
    val avatar: String? = null
)

data class Message(
    val id: String = UUID.randomUUID().toString(),
    val senderId: String,
    val chatId: String,
    val content: String,
    val timestamp: Instant = Instant.now(),
    val read: Boolean = false,
    val edited: Boolean = false,
    val type: MessageType = MessageType.TEXT
)

enum class MessageType { TEXT, IMAGE, FILE, SYSTEM }

data class Chat(
    val id: String = UUID.randomUUID().toString(),
    val participants: List<User>,
    val createdAt: Instant = Instant.now(),
    var lastMessage: Message? = null
)

// ===== الأحداث =====
sealed class ChatEvent {
    data class MessageReceived(val message: Message) : ChatEvent()
    data class MessageEdited(val message: Message) : ChatEvent()
    data class MessageDeleted(val messageId: String) : ChatEvent()
    data class UserTyping(val userId: String, val chatId: String) : ChatEvent()
    data class UserJoined(val user: User, val chatId: String) : ChatEvent()
    data class UserLeft(val userId: String, val chatId: String) : ChatEvent()
}

// ===== خدمة الدردشة =====
class ChatService {
    private val _events = MutableSharedFlow<ChatEvent>()
    val events: SharedFlow<ChatEvent> = _events.asSharedFlow()

    private val chats = mutableMapOf<String, Chat>()
    private val messages = mutableMapOf<String, MutableList<Message>>()
    private val users = mutableMapOf<String, User>()
    private val typingIndicators = mutableMapOf<String, MutableSet<String>>()

    fun registerUser(user: User) {
        users[user.id] = user
    }

    fun createChat(participants: List<User>): Chat {
        val chat = Chat(participants = participants)
        chats[chat.id] = chat
        messages[chat.id] = mutableListOf()
        return chat
    }

    suspend fun sendMessage(
        senderId: String,
        chatId: String,
        content: String,
        type: MessageType = MessageType.TEXT
    ): Message {
        require(users.containsKey(senderId)) { "المستخدم غير موجود" }
        require(chats.containsKey(chatId)) { "المحادثة غير موجودة" }

        val message = Message(
            senderId = senderId,
            chatId = chatId,
            content = content,
            type = type
        )

        messages.getOrPut(chatId) { mutableListOf() }.add(message)
        chats[chatId]?.lastMessage = message

        _events.emit(ChatEvent.MessageReceived(message))
        return message
    }

    suspend fun editMessage(messageId: String, newContent: String): Message? {
        for (msgs in messages.values) {
            val index = msgs.indexOfFirst { it.id == messageId }
            if (index >= 0) {
                val updated = msgs[index].copy(content = newContent, edited = true)
                msgs[index] = updated
                _events.emit(ChatEvent.MessageEdited(updated))
                return updated
            }
        }
        return null
    }

    suspend fun deleteMessage(messageId: String) {
        for (msgs in messages.values) {
            if (msgs.removeIf { it.id == messageId }) {
                _events.emit(ChatEvent.MessageDeleted(messageId))
                return
            }
        }
    }

    suspend fun setTyping(userId: String, chatId: String, typing: Boolean) {
        val set = typingIndicators.getOrPut(chatId) { mutableSetOf() }
        if (typing) {
            set.add(userId)
            _events.emit(ChatEvent.UserTyping(userId, chatId))
        } else {
            set.remove(userId)
        }
    }

    fun getMessages(chatId: String, limit: Int = 50, offset: Int = 0): List<Message> {
        return messages[chatId]
            ?.sortedByDescending { it.timestamp }
            ?.drop(offset)
            ?.take(limit)
            ?.sortedBy { it.timestamp }
            ?: emptyList()
    }

    fun searchMessages(chatId: String, query: String): List<Message> {
        return messages[chatId]
            ?.filter { it.content.contains(query, ignoreCase = true) }
            ?: emptyList()
    }

    // Flow للمحادثة الحية
    fun observeChat(chatId: String): Flow<Message> = flow {
        events
            .filterIsInstance<ChatEvent.MessageReceived>()
            .filter { it.message.chatId == chatId }
            .collect { emit(it.message) }
    }

    fun observeTyping(chatId: String): Flow<String> = flow {
        events
            .filterIsInstance<ChatEvent.UserTyping>()
            .filter { it.chatId == chatId }
            .collect { event ->
                val user = users[event.userId]
                user?.let { emit(it.name) }
            }
    }

    fun getUnreadCount(userId: String, chatId: String): Int {
        return messages[chatId]
            ?.count { it.senderId != userId && !it.read }
            ?: 0
    }

    suspend fun markAsRead(chatId: String, userId: String) {
        messages[chatId]?.forEachIndexed { index, msg ->
            if (msg.senderId != userId && !msg.read) {
                messages[chatId]!![index] = msg.copy(read = true)
            }
        }
    }

    fun getChatsForUser(userId: String): List<Chat> {
        return chats.values.filter { chat ->
            chat.participants.any { it.id == userId }
        }
    }
}

// ===== البرنامج الرئيسي =====
fun main() = runBlocking {
    val service = ChatService()

    // تسجيل المستخدمين
    val ahmed = User("u1", "أحمد", "ahmed@example.com")
    val sara = User("u2", "سارة", "sara@example.com")
    val khaled = User("u3", "خالد", "khaled@example.com")

    service.registerUser(ahmed)
    service.registerUser(sara)
    service.registerUser(khaled)

    // إنشاء محادثة
    val chat = service.createChat(listOf(ahmed, sara, khaled))
    println("تم إنشاء المحادثة: ${chat.id}")

    // مراقبة الرسائل في coroutine منفصل
    val observer = launch {
        service.observeChat(chat.id).collect { msg ->
            val sender = service.getChatsForUser(msg.senderId).firstOrNull()
                ?.participants?.find { it.id == msg.senderId }
            println("[${msg.timestamp}] ${sender?.name ?: "مجهول"}: ${msg.content}")
        }
    }

    // مراقبة الكتابة
    val typingObserver = launch {
        service.observeTyping(chat.id).collect { name ->
            println("... $name يكتب")
        }
    }

    // إرسال رسائل
    delay(100)
    service.sendMessage(ahmed.id, chat.id, "مرحباً بالجميع!")
    delay(500)
    service.setTyping(sara.id, chat.id, true)
    delay(1000)
    service.setTyping(sara.id, chat.id, false)
    service.sendMessage(sara.id, chat.id, "أهلاً أحمد! كيف حالك؟")
    delay(500)
    service.sendMessage(khaled.id, chat.id, "مرحباً! أنا بخير، شكراً")
    delay(500)

    // تعديل رسالة
    val lastMsg = service.getMessages(chat.id).last()
    service.editMessage(lastMsg.id, "مرحباً! أنا بخير، شكراً جزيلاً")
    delay(500)

    // عرض الإحصائيات
    println("\n=== إحصائيات ===")
    println("عدد الرسائل: ${service.getMessages(chat.id).size}")
    println("غير المقروءة لأحمد: ${service.getUnreadCount(ahmed.id, chat.id)}")

    // بحث
    println("\n=== نتائج البحث عن 'مرحباً' ===")
    service.searchMessages(chat.id, "مرحباً").forEach {
        println("- ${it.content}")
    }

    // إلغاء المراقبة
    observer.cancel()
    typingObserver.cancel()

    println("\n✓ انتهى التطبيق")
}

