import Foundation

// ===== النماذج =====
struct Article: Codable, Identifiable, Hashable {
    let id: Int
    let title: String
    let body: String
    let userId: Int
    let tags: [String]
    let createdAt: Date
    var isFavorite: Bool = false

    enum CodingKeys: String, CodingKey {
        case id, title, body, userId, tags
        case createdAt = "created_at"
    }
}

struct Comment: Codable, Identifiable {
    let id: Int
    let postId: Int
    let name: String
    let email: String
    let body: String
}

// ===== الأخطاء =====
enum NetworkError: LocalizedError {
    case invalidURL
    case noData
    case decodingError(Error)
    case serverError(Int)
    case unknown(Error)

    var errorDescription: String? {
        switch self {
        case .invalidURL: return "الرابط غير صحيح"
        case .noData: return "لا توجد بيانات"
        case .decodingError(let e): return "خطأ في فك الترميز: \(e.localizedDescription)"
        case .serverError(let code): return "خطأ من الخادم: \(code)"
        case .unknown(let e): return e.localizedDescription
        }
    }
}

// ===== عميل الشبكة =====
actor NetworkClient {
    private let session: URLSession
    private let decoder: JSONDecoder
    private let baseURL: URL
    private var cache: [String: Data] = [:]

    init(baseURL: URL) {
        self.baseURL = baseURL
        let config = URLSessionConfiguration.default
        config.timeoutIntervalForRequest = 30
        config.requestCachePolicy = .returnCacheDataElseLoad
        self.session = URLSession(configuration: config)

        self.decoder = JSONDecoder()
        let formatter = DateFormatter()
        formatter.dateFormat = "yyyy-MM-dd'T'HH:mm:ssZ"
        decoder.dateDecodingStrategy = .formatted(formatter)
    }

    func fetch<T: Decodable>(_ type: T.Type, endpoint: String) async throws -> T {
        guard let url = URL(string: endpoint, relativeTo: baseURL) else {
            throw NetworkError.invalidURL
        }

        do {
            let (data, response) = try await session.data(from: url)

            guard let httpResponse = response as? HTTPURLResponse else {
                throw NetworkError.noData
            }

            guard (200...299).contains(httpResponse.statusCode) else {
                throw NetworkError.serverError(httpResponse.statusCode)
            }

            cache[endpoint] = data
            return try decoder.decode(T.self, from: data)
        } catch let error as NetworkError {
            throw error
        } catch let error as DecodingError {
            throw NetworkError.decodingError(error)
        } catch {
            throw NetworkError.unknown(error)
        }
    }

    func post<T: Encodable, R: Decodable>(_ type: R.Type, endpoint: String, body: T) async throws -> R {
        guard let url = URL(string: endpoint, relativeTo: baseURL) else {
            throw NetworkError.invalidURL
        }

        var request = URLRequest(url: url)
        request.httpMethod = "POST"
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        request.httpBody = try JSONEncoder().encode(body)

        let (data, _) = try await session.data(for: request)
        return try decoder.decode(R.self, from: data)
    }
}

// ===== Generic Repository =====
protocol Repository {
    associatedtype Item: Codable & Identifiable

    func getAll() async throws -> [Item]
    func getById(_ id: Int) async throws -> Item?
    func search(query: String) async throws -> [Item]
}

class ArticleRepository: Repository {
    typealias Item = Article

    private let client: NetworkClient
    private var cache: [Article] = []

    init(client: NetworkClient) {
        self.client = client
    }

    func getAll() async throws -> [Article] {
        if !cache.isEmpty { return cache }
        let articles: [Article] = try await client.fetch([Article].self, endpoint: "/posts")
        cache = articles
        return articles
    }

    func getById(_ id: Int) async throws -> Article? {
        if let cached = cache.first(where: { $0.id == id }) { return cached }
        return try await client.fetch(Article.self, endpoint: "/posts/\(id)")
    }

    func search(query: String) async throws -> [Article] {
        let all = try await getAll()
        return all.filter {
            $0.title.localizedCaseInsensitiveContains(query) ||
            $0.body.localizedCaseInsensitiveContains(query)
        }
    }

    func toggleFavorite(_ id: Int) async throws -> Article? {
        guard let index = cache.firstIndex(where: { $0.id == id }) else { return nil }
        cache[index].isFavorite.toggle()
        return cache[index]
    }
}

// ===== خدمة المقالات =====
@MainActor
class ArticleViewModel: ObservableObject {
    @Published var articles: [Article] = []
    @Published var isLoading = false
    @Published var errorMessage: String?
    @Published var searchQuery = ""

    private let repository: ArticleRepository

    init(repository: ArticleRepository) {
        self.repository = repository
    }

    func loadArticles() async {
        isLoading = true
        errorMessage = nil
        do {
            articles = try await repository.getAll()
        } catch {
            errorMessage = error.localizedDescription
        }
        isLoading = false
    }

    func search() async {
        guard !searchQuery.isEmpty else {
            await loadArticles()
            return
        }
        isLoading = true
        do {
            articles = try await repository.search(query: searchQuery)
        } catch {
            errorMessage = error.localizedDescription
        }
        isLoading = false
    }

    func toggleFavorite(_ article: Article) async {
        if let updated = try? await repository.toggleFavorite(article.id) {
            if let index = articles.firstIndex(where: { $0.id == article.id }) {
                articles[index] = updated
            }
        }
    }
}

// ===== البرنامج الرئيسي =====
@main
struct ArticleApp {
    static func main() async {
        let baseURL = URL(string: "https://jsonplaceholder.typicode.com")!
        let client = NetworkClient(baseURL: baseURL)
        let repository = ArticleRepository(client: client)
        let viewModel = await ArticleViewModel(repository: repository)

        print("جاري تحميل المقالات...")
        await viewModel.loadArticles()

        if let error = viewModel.errorMessage {
            print("خطأ: \(error)")
            return
        }

        print("\n=== المقالات (\(viewModel.articles.count)) ===")
        for article in viewModel.articles.prefix(5) {
            print("#\(article.id) \(article.title)")
            print("  \(article.body.prefix(80))...")
        }

        // بحث
        print("\n=== البحث عن 'qui' ===")
        viewModel.searchQuery = "qui"
        await viewModel.search()
        for article in viewModel.articles {
            print("- \(article.title)")
        }
    }
}
